<?php
namespace App\Services\Warehouse\Purchasing;
use Illuminate\Support\Facades\DB; use Illuminate\Support\Str; use Illuminate\Validation\ValidationException;
class WarehousePurchasingFinanceService{
 public function generateInvoice(string $stockInId,object $user):object{return DB::transaction(function()use($stockInId,$user){$si=DB::table('wh_stock_ins')->lockForUpdate()->where('id',$stockInId)->first();if(!$si||$si->status!=='approved')throw ValidationException::withMessages(['stock_in_id'=>'Stock In harus approved sebelum Purchase Invoice dibuat.']);$old=DB::table('wh_supplier_invoices')->where('stock_in_id',$stockInId)->first();if($old)return $old;$po=DB::table('wh_supplier_purchase_orders')->where('id',$si->purchase_order_id)->first();if(!$po)throw ValidationException::withMessages(['purchase_order_id'=>'PO Warehouse tidak ditemukan.']);$id=(string)Str::ulid();DB::table('wh_supplier_invoices')->insert(['id'=>$id,'invoice_number'=>$this->number('WH-PINV'),'purchase_order_id'=>$po->id,'stock_in_id'=>$si->id,'warehouse_id'=>$si->warehouse_id,'supplier_source_id'=>$po->supplier_source_id,'invoice_date'=>now()->toDateString(),'due_date'=>now()->addDays(30)->toDateString(),'currency_code'=>$po->currency??'IDR','status'=>'issued','idempotency_key'=>'stock-in:'.$si->id,'issued_by_user_id'=>$user->id,'issued_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);$items=DB::table('wh_stock_in_items as s')->join('wh_supplier_purchase_order_items as p','p.id','=','s.purchase_order_item_id')->where('s.stock_in_id',$si->id)->select('s.*','p.actual_unit_price','p.estimated_unit_price')->get();$sub=0;foreach($items as $x){$qty=(float)$x->accepted_qty_base;$unit=(float)($x->unit_cost?:($x->actual_unit_price?:$x->estimated_unit_price));$line=$qty*$unit;$sub+=$line;DB::table('wh_supplier_invoice_items')->insert(['id'=>(string)Str::ulid(),'supplier_invoice_id'=>$id,'purchase_order_item_id'=>$x->purchase_order_item_id,'stock_in_item_id'=>$x->id,'sku_id'=>$x->sku_id,'quantity_base'=>$qty,'unit_price'=>$unit,'line_subtotal'=>$line,'inventory_cost_total'=>$line,'effective_unit_cost'=>$unit,'source_snapshot'=>json_encode(['stock_in_number'=>$si->stock_in_number]),'created_at'=>now(),'updated_at'=>now()]);}DB::table('wh_supplier_invoices')->where('id',$id)->update(['subtotal'=>$sub,'grand_total'=>$sub,'balance_due'=>$sub,'updated_at'=>now()]);$this->event('supplier_invoice',$id,'issued',['stock_in_id'=>$si->id,'total'=>$sub],$user->id);return DB::table('wh_supplier_invoices')->where('id',$id)->first();});}
 public function allocateLandedCost(string $invoiceId,array $data,object $user):object{return DB::transaction(function()use($invoiceId,$data,$user){$inv=DB::table('wh_supplier_invoices')->lockForUpdate()->where('id',$invoiceId)->whereIn('status',['issued','partially_paid'])->first();if(!$inv)throw ValidationException::withMessages(['invoice'=>'Purchase Invoice terbuka tidak ditemukan.']);$amount=(float)$data['amount'];if($amount<=0)throw ValidationException::withMessages(['amount'=>'Landed cost harus lebih besar dari nol.']);DB::table('wh_landed_costs')->insert(['id'=>(string)Str::ulid(),'supplier_invoice_id'=>$invoiceId,'cost_type'=>$data['cost_type'],'description'=>$data['description']??null,'amount'=>$amount,'allocation_method'=>$data['allocation_method']??'value','created_by_user_id'=>$user->id,'created_at'=>now(),'updated_at'=>now()]);$items=DB::table('wh_supplier_invoice_items')->where('supplier_invoice_id',$invoiceId)->get();$base=$items->sum(fn($x)=>($data['allocation_method']??'value')==='quantity'?(float)$x->quantity_base:(float)$x->line_subtotal);foreach($items as $x){$weight=$base>0?((($data['allocation_method']??'value')==='quantity'?(float)$x->quantity_base:(float)$x->line_subtotal)/$base):0;$alloc=$amount*$weight;$new=(float)$x->landed_cost_allocated+$alloc;$total=(float)$x->line_subtotal+$new;$unit=(float)$x->quantity_base>0?$total/(float)$x->quantity_base:0;DB::table('wh_supplier_invoice_items')->where('id',$x->id)->update(['landed_cost_allocated'=>$new,'inventory_cost_total'=>$total,'effective_unit_cost'=>$unit,'updated_at'=>now()]);}DB::table('wh_supplier_invoices')->where('id',$invoiceId)->update(['landed_cost_total'=>DB::raw('landed_cost_total + '.$amount),'grand_total'=>DB::raw('grand_total + '.$amount),'balance_due'=>DB::raw('balance_due + '.$amount),'updated_at'=>now()]);$this->event('supplier_invoice',$invoiceId,'landed_cost_allocated',$data,$user->id);return DB::table('wh_supplier_invoices')->where('id',$invoiceId)->first();});}
 public function postPayment(array $data,object $user):object{return DB::transaction(function()use($data,$user){$inv=DB::table('wh_supplier_invoices')->lockForUpdate()->where('id',$data['supplier_invoice_id'])->whereIn('status',['issued','partially_paid'])->first();if(!$inv)throw ValidationException::withMessages(['supplier_invoice_id'=>'Purchase Invoice terbuka tidak ditemukan.']);$amount=(float)$data['amount'];if($amount<=0||$amount>(float)$inv->balance_due+0.0001)throw ValidationException::withMessages(['amount'=>'Pembayaran tidak valid atau melebihi saldo.']);$key=$data['idempotency_key']??('supplier-invoice:'.$inv->id.':'.Str::uuid());if($old=DB::table('wh_supplier_payments')->where('idempotency_key',$key)->first())return $old;$id=(string)Str::ulid();DB::table('wh_supplier_payments')->insert(['id'=>$id,'payment_number'=>$this->number('WH-PAY'),'warehouse_id'=>$inv->warehouse_id,'supplier_source_id'=>$inv->supplier_source_id,'payment_date'=>$data['payment_date']??now()->toDateString(),'payment_method'=>$data['payment_method'],'reference_number'=>$data['reference_number']??null,'amount'=>$amount,'status'=>'posted','idempotency_key'=>$key,'notes'=>$data['notes']??null,'posted_by_user_id'=>$user->id,'posted_at'=>now(),'created_at'=>now(),'updated_at'=>now()]);DB::table('wh_supplier_payment_allocations')->insert(['id'=>(string)Str::ulid(),'supplier_payment_id'=>$id,'supplier_invoice_id'=>$inv->id,'allocated_amount'=>$amount,'created_at'=>now(),'updated_at'=>now()]);$paid=(float)$inv->paid_total+$amount;$bal=max(0,(float)$inv->grand_total-$paid);DB::table('wh_supplier_invoices')->where('id',$inv->id)->update(['paid_total'=>$paid,'balance_due'=>$bal,'status'=>$bal<=0.0001?'paid':'partially_paid','updated_at'=>now()]);$this->event('supplier_payment',$id,'posted',['invoice_id'=>$inv->id,'amount'=>$amount],$user->id);return DB::table('wh_supplier_payments')->where('id',$id)->first();});}
 public function voidPayment(string $id,string $reason,object $user):object{return DB::transaction(function()use($id,$reason,$user){$p=DB::table('wh_supplier_payments')->lockForUpdate()->where('id',$id)->where('status','posted')->first();if(!$p)throw ValidationException::withMessages(['payment'=>'Pembayaran posted tidak ditemukan.']);$a=DB::table('wh_supplier_payment_allocations')->where('supplier_payment_id',$id)->first();if($a){$inv=DB::table('wh_supplier_invoices')->lockForUpdate()->where('id',$a->supplier_invoice_id)->first();$paid=max(0,(float)$inv->paid_total-(float)$a->allocated_amount);$bal=max(0,(float)$inv->grand_total-$paid);DB::table('wh_supplier_invoices')->where('id',$inv->id)->update(['paid_total'=>$paid,'balance_due'=>$bal,'status'=>$paid>0?'partially_paid':'issued','updated_at'=>now()]);}DB::table('wh_supplier_payments')->where('id',$id)->update(['status'=>'void','notes'=>trim(($p->notes?$p->notes."\n":'').'VOID: '.$reason),'updated_at'=>now()]);$this->event('supplier_payment',$id,'voided',['reason'=>$reason],$user->id);return DB::table('wh_supplier_payments')->where('id',$id)->first();});}
 public function dashboard(array $ids):array{$i=DB::table('wh_supplier_invoices')->whereIn('warehouse_id',$ids)->whereIn('status',['issued','partially_paid','paid']);return ['purchases'=>(clone $i)->sum('grand_total'),'payable'=>(clone $i)->sum('balance_due'),'landed_cost'=>(clone $i)->sum('landed_cost_total'),'overdue'=>(clone $i)->where('balance_due','>',0)->where('due_date','<',now()->toDateString())->sum('balance_due'),'open_pr'=>DB::table('wh_purchase_requests')->whereIn('warehouse_id',$ids)->whereIn('status',['draft','submitted'])->count(),'open_po'=>DB::table('wh_supplier_purchase_orders')->whereIn('warehouse_id',$ids)->whereNotIn('status',['completed','cancelled'])->count()];}
 private function number(string $p):string{return $p.'-'.now()->format('Ymd').'-'.strtoupper(Str::random(6));}private function event(string $t,string $id,string $e,array $p,?string $u):void{DB::table('wh_purchasing_events')->insert(['id'=>(string)Str::ulid(),'document_type'=>$t,'document_id'=>$id,'event_type'=>$e,'payload'=>json_encode($p),'actor_user_id'=>$u,'created_at'=>now(),'updated_at'=>now()]);}}
